properties.query:
let Tier0BuiltinGroupSids = dynamic(["S-1-5-32-544", "S-1-5-32-548", "S-1-5-32-549", "S-1-5-32-550", "S-1-5-32-551"]);
// Domain Admins, Schema Admins, Enterprise Admins, Group Policy Creator Owners, Key Admins, Enterprise Key Admins
let Tier0GroupRids = dynamic(["512", "518", "519", "520", "526", "527"]);
SecurityEvent
// 4728 global, 4732 domain local, 4756 universal security group
| where EventID in (4728, 4732, 4756)
| extend GroupRid = extract(@"-(\d+)$", 1, TargetSid)
| where TargetSid in (Tier0BuiltinGroupSids) or (TargetSid startswith "S-1-5-21-" and GroupRid in (Tier0GroupRids))
| project TimeGenerated, Computer, Activity, GroupName = TargetUserName, GroupSid = TargetSid, MemberName, MemberSid, SubjectAccount, SubjectUserName, SubjectUserSid
